#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later

"""Regenerate the app version used by Settings from app/pubspec.yaml."""

import re
from pathlib import Path


app = Path(__file__).resolve().parents[1] / "app"
version = re.search(r"^version:\s*(\S+)", (app / "pubspec.yaml").read_text(),
                    re.MULTILINE)
if version is None:
    raise SystemExit("Missing version in app/pubspec.yaml")
(app / "lib/src/app_version.dart").write_text(
    "// SPDX-License-Identifier: GPL-3.0-or-later\n\n"
    "// Generated by tools/generate_app_version.py.\n"
    f"const appVersion = '{version[1]}';\n",
)
